function LadderCompetionMainDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)

        -- all teamNode
        self.teamNodeList_ = {}
        for teamIndex = 1, TeamCardCount do
            local teamGroupGo = self['TeamCardGroup' .. teamIndex]
            local teamNodeLua = not isNull(teamGroupGo) and CfUtils.GetLuaScr(teamGroupGo, TeamNodeLuaPath) or nil
            if not isNull(teamNodeLua) then
                self.teamNodeList_[teamIndex] = teamNodeLua
            end
        end

        -- read teamInfo
        local teamInfoData = teamComponent:GetTeamInfoByQuestId(LadderQuestId, 1)
        self.teamDojoList_ = teamInfoData.cardsInfo
        
        -- update nodeList
        for _, teamNodeLua in ipairs(self.teamNodeList_) do
            teamNodeLua:SetAllNodeList(self.teamNodeList_)
            teamNodeLua:SetClickNodeCb(Bind(self, self.OnClickTeamNodeCb_))
            teamNodeLua:SetDragToTargetCb(Bind(self, self.OnDragTeamNodeToTargetCb_))
        end

        -- update redPoint
        CfUtils.SetActive(self.BtnTaskRedPoint, false)
        CfUtils.SetActive(self.BtnStoreRedPoint, false)

        -- bind listener
        SetButtonAction(self.BtnStart, Bind(self, self.OnClickStartButtonHandler_))
        SetButtonAction(self.BtnTask, Bind(self, self.OnClickTaskButtonHandler_))
        SetButtonAction(self.BtnRewards, Bind(self, self.OnClickRewardsButtonHandler_))
        SetButtonAction(self.BtnRanking, Bind(self, self.OnClickRankingButtonHandler_))
        SetButtonAction(self.BtnStore, Bind(self, self.OnClickStoreButtonHandler_))
        SetButtonAction(self.BtnOneStep, Bind(self, self.OnClickOneStepButtonHandler_))
        SetButtonAction(self.SkillInfo, Bind(self, self.OnBtnMergeSkill))
        SetButtonAction(self.BtnStreakDetail, Bind(self, self.OnClickBattleRecordHandler_))
        self.eventOnLadderRedPointChangeCb_ = Events.AddListener(Constants.EventNames.LadderRedPointChange, Bind(self, self.OnLadderRedPointChangeEventHandler_))
        self.EventSkillCompoundChange = Events.AddListener(Constants.EventNames.SkillCompoundChange, Bind(self, self.FillMergeSkillInfo))

        -- 红点
        GameUtils.BindRedPoint(Constants.RedPointConst.LadderCompetionTask, self.BtnTask, true)
    end))
    return coWait
end


