---@return CardDojo[]
function LadderCompetionMainDialog:GetUsableCardsData()
    local ownedCards  = cardComponent:GetAllCardTable()
    local usableCards = {}
    for _, cardDojo in ipairs(ownedCards) do
        if not self.disableIdMap_[tostring(cardDojo.cardId)] then
