function LadderCompetionMainDialog:RequestHomeData_()
    -- close matchDialog
    UIModule.CloseDialogById(Constants.UITypeIds.LadderCompetionMatchDialog)

    -- request homeData
    GameUtils.Request(Interfaces.LADDER_HOME, {  }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            if isNull(self.controller) then return end

            -- 剩余每日购买数量
            local playerDojo = GameUtils.GetPlayerDojo()
            if isNotNull(playerDojo) then
                playerDojo.ladderTicketResidueBuyTimes = response.data.ladderTicketResidueBuyTimes
            end

            -- update homeData
            self.ladderDojo:Fill(response.data)
            
            self:ChangeBtnStatus()

            -- update myself info
            self:UpdateMyselfGrade_()

            -- start countDown
            self:StartEntryCountdown_()

            -- update redPoint
            --self:OnLadderRedPointChangeEventHandler_(self.activityUuid_, self.ladderDojo.redDotHint)

            -- 赛季结算
            local localSeasonKey = Constants.PlayerPrefsType.LadderCompetionSeasonId
            local localSeason  = checkInt(CfUtils.GetLocalData(localSeasonKey, '0'))
            if localSeason == self.ladderDojo.lastSeason then   --防止多次结算
                if (self.ladderDojo.season - self.ladderDojo.lastSeason) == 1 then
                    UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionSeasonSettlementDialog, {
                        score = self.ladderDojo.score,
                        segment = self.ladderDojo.segment,
                        subSegment = self.ladderDojo.subSegment,
                        lastScore = self.ladderDojo.lastScore,
                        lastSegment = self.ladderDojo.lastSegment,
                        lastSubSegment = self.ladderDojo.lastSubSegment,
                    }))
                end
            end
            CfUtils.WriteLocalData(localSeasonKey, self.ladderDojo.season)
            
            --UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionDanAnimDialog, {
            --            oldSegmentId = 3,
            --            newSegmentId = 2,
            --            oldSubSegmentId = 5,
            --            newSubSegmentId = 3
            --        }))
            --UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionSeasonSettlementDialog, {
            --    score = 1111,
            --    segment = 1,
            --    subSegment = 2,
            --    lastScore = 444,
            --    lastSegment = 1,
            --    lastSubSegment = 1,
            --}))
        end
    end)
end


---@param oldTeamIdList string[] | nil
function LadderCompetionMainDialog:UpdateAllTeamInfo_(oldTeamIdList)
    -- 计算共鸣的情绪 id列表
    local emotionBonusDict = CardUtils.CalculateEmotionBonusDict(self.teamDojoList_)

    -- all cardNode
    for nodeIndex = 1, #self.teamNodeList_ do
        local memberDojo  = self.teamDojoList_[nodeIndex]
        local showEmotionBonus = CardUtils.ConsumeEmotionBonusDict(memberDojo, emotionBonusDict)
        self:UpdateTeamCardAt_(nodeIndex, oldTeamIdList and oldTeamIdList[nodeIndex] or nil, showEmotionBonus)
    end

    -- team power
    CfUtils.FillText(self.TxtTeamPower, checkNumber(teamComponent:GetTeamFightingPower(self.teamDojoList_)))

    -- 情绪共鸣
    GameUtils.RefreshLineupBonusNode(self.FightTeamBonusNode, self.teamNodeList_, true, true)
end


function LadderCompetionMainDialog:UpdateTeamCardAt_(nodeIndex, oldCardGuid, showEmotionBonus)
    local memberDojo  = self.teamDojoList_[nodeIndex]
    local teamNodeLua = self.teamNodeList_[nodeIndex]
    if memberDojo and not IsNull(teamNodeLua) then
        teamNodeLua:SetCardIndex(nodeIndex)
        teamNodeLua:SetTeamDojo(memberDojo, oldCardGuid)
        
        -- 情绪共鸣
        if isNotNull(showEmotionBonus) then
            teamNodeLua:SetEmotionBonusLoopFX(showEmotionBonus)
            if showEmotionBonus then
                teamNodeLua:ShowEmotionBonusFlyFX(self.FightTeamBonusNode.gameObject)
            else
                teamNodeLua:CloseEmotionBonusFlyFX()
            end
        end
    end
    -- team power
    CfUtils.FillText(self.TxtPower, checkNumber(teamComponent.GetTeamFightingPower(self.teamDojoList_)))
end

---我的信息可能需要更新
function LadderCompetionMainDialog:UpdateMyselfGrade_()
    ---@type CommonPlayerHeadNode
    local playerHeadLua = CfUtils.GetLuaScr(self.PlayerHead, PlayerHeadLuaPath)
    if not isNull(playerHeadLua) then
        playerHeadLua:FreshBaseUI()
    end

    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()
    CfUtils.FillText(self.TxtPlayerName, playerDojo.playerName)
    CfUtils.FillText(self.TxtLv, string.format('LV.%d', playerDojo.level))

    ---@type LadderGradeVo
    ---大段位下有5个小段位
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    local ladderGradeVo  = ladderCompetionUtils.GetGradeVo(self.ladderDojo.segment, self.ladderDojo.subSegment)
    local havLadderGrade = ladderGradeVo ~= nil
    CfUtils.SetActive(self.TxtSegment, havLadderGrade)
    CfUtils.SetActive(self.ImgPosition, havLadderGrade)
    local starCount = checkNumber(self.ladderDojo.subSegment)
    for i = 1, 5 do
        local child = self.StarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
    
    if ladderGradeVo then
        CfUtils.FillText(self.TxtSegment, ladderGradeVo.name2)
        CfUtils.FillImage(self.ImgPosition, ladderGradeVo.icon)
    end

    CfUtils.FillText(self.TxtScore, self.ladderDojo.score)
    if checkNumber(self.ladderDojo.ranking) == 0 then
        CfUtils.FillText(self.TxtRank, '--')
    else
        CfUtils.FillText(self.TxtRank, self.ladderDojo.ranking)
    end
    CfUtils.FillText(self.TxtStreak, self.ladderDojo.winStreak)
end

function LadderCompetionMainDialog:StartEntryCountdown_()
    if checkInt(self.ladderDojo.status) == 2 then
        CfUtils.FillText(self.TxtTimeIntro, localize('结束剩余时间'))
    elseif checkInt(self.ladderDojo.status) == 1 then
        CfUtils.FillText(self.TxtTimeIntro, localize('开始剩余时间'))
    end
    self:ClearEntryCountdown_()

    if checkInt(self.ladderDojo.status) > 0 then
        local leftSeconds = math.max(checkInt(self.ladderDojo.remainSeconds), 0)
        self.countdownHandler_ = CDTimerModule:AddCD(1, function(countTimes, timerId)
            CfUtils.FillText(self.TxtLeftTime, CfUtils.GetTimeHMS2(countTimes))
            if countTimes <= 0 then
                -- 防止剩余时间为0时，无限立即刷新
                self.countdownHandler_ = CDTimerModule:AddCD(1, function()
                    self:RequestHomeData_()
                end, 1, false, true)
            end
        end, leftSeconds, true, true)
    else
        CfUtils.FillText(self.TxtLeftTime, '')
    end
end


function LadderCompetionMainDialog:ClearEntryCountdown_()
    if not isNull(self.countdownHandler_) then
        CDTimerModule:RemoveCD(self.countdownHandler_)
        self.countdownHandler_ = nil
    end
end


