function LadderCompetionMainDialog:ChangeBtnStatus()
    if checkInt(self.ladderDojo.status) == 2 then
        self.BtnStart:ResetFontStyle("B1", localize("开始匹配"))
    else
        self.BtnStart:ResetFontStyle("B17", localize("尚未开启"))
    end
end

function LadderCompetionMainDialog:OnClickStartButtonHandler_()
    if not self.isControllable_ then return end
    
    local ticketNum = GoodsUtils.GetThingNo(LadderTicketId)
    if ticketNum <= 0 then
        GameUtils.Toast(localize('挑战许可证不足'))
        return
    end
    
    local isAllEmptyTeam = true
    for _, teamDojo in ipairs(self.teamDojoList_) do
        if checkInt(teamDojo.cardId) > 0 then
            isAllEmptyTeam = false
        end
    end
    
    if isAllEmptyTeam then
        GameUtils.Toast(localize('队伍配置为空，请先编队'))
        return
    end
    
    if checkInt(self.ladderDojo.status) == 2 then
        if KNManager.isConnected then
            UIModule.OpenDialog(UIArgs(Constants.UITypeIds.LadderCompetionMatchDialog, {
                ladderHomeDojo = self.ladderDojo,
                matchSuccessCb = function()
                    self.isMatchSuccess_ = true
                    self.isControllable_ = false
                    self.controller:Close()
                end
            }))
        else
            GameUtils.Toast(localize('网络环境异常，请稍后尝试'))
        end
    elseif checkInt(self.ladderDojo.status) == 1 then
        GameUtils.Toast(localize('比赛还未开始，请耐心等待'))
    end
end


