--绘制合卡技
function LadderCompetionMainDialog:FillMergeSkillInfo()
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id3007)
    KTool.SetActive(self.SkillInfo, false) -- 吞设定咯
    --迷宫不要合卡技
    if not isUnlock then
        --KTool.SetActive(self.SkillInfo, false)
        KTool.SetActive(self.Lock, true)
        SetButtonAction(self.Lock, function()
            GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id3007))
        end)
    else
        -- KTool.SetActive(self.SkillInfo, true)
        KTool.SetActive(self.Lock, false)

        local catId = teamComponent:GetCurSkillCompoundId(LadderQuestId, 1)

        KTool.SetActive(self.Normal1, checkNumber(catId) > 0)
        KTool.SetActive(self.AddSkill, checkNumber(catId) <= 0)
        local catEggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        local data = catEggComponent:GetCatById(catId)
        if data then
            local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(data.catId)
            if checkNumber(data.star) >= MaidCoffeeUtils.CalcCatRollMaxStar() then
                CfUtils.FillImage(self.ImgCardSkill, vo.picture2)
            else
                CfUtils.FillImage(self.ImgCardSkill, vo.picture1)
            end

            local data = QuestConfMgr:GetInstance():GetMergeSkillData(vo.id)
            local curNum = checkNumber(data.cafeEnergy)
            local maxNum = MaidCoffeeUtils.CalcCatRollEnergyLimit(vo.id, data.level)
            CfUtils.FillText(self.TextNumber, localize("<size=48>_num1_</size>/_num2_", {_num1_ = curNum, _num2_ = maxNum}))
        end
    end
end

function LadderCompetionMainDialog:OnClickOneStepButtonHandler_()
    if not self.isControllable_ then return end

    ---@type CardDojo[]
    local allCardsData  = CardUtils.SortCardBySortType(self:GetUsableCardsData(), Constants.SortType.CombatPower, true)
    local teamCardCount = teamComponent:GetMaxSelectNum(LadderQuestId, Constants.ChooseCardStatus.LadderCompetion, 1)
    for cardIndex = #allCardsData, 1, -1 do
        if self.disableIdMap_[tostring(allCardsData[cardIndex].cardId)] then
            table.remove(allCardsData, cardIndex)
        end
    end

    self.teamDojoList_  = {}

    local restPositionNum = 4 --初始空位数量
    if restPositionNum > 0 then

        if true then --第一次点击时才与服务器通讯
            --取得所有卡牌
            local t = allCardsData

            for i = 1, table.count(t) do
                if restPositionNum > 0 then
                    local cardData = t[i]
                    local isCanJoinTeam = true
                    if isCanJoinTeam then
                        print(table.dump(self.teamDojoList_))
                        --过滤掉不符合条件的数据
                        if teamComponent:IsCanJoinTeam(self.teamDojoList_, cardData)  then
                            --添加到编队中
                            local refId = cardData.id
                            local type = (checkNumber(cardData.isAssistant) == 1 and Constants.TeamMemberType.HelperCard or Constants.TeamMemberType.PlayerCard)
                            table.insert(self.teamDojoList_, CfUtils.GetTeamMemberDojo{
                                type = type,
                                refId = refId,
                                cardId = cardData.cardId
                            })
                            restPositionNum = restPositionNum - 1
                            if restPositionNum <= 0 then
                                break
                            end
                        end
                    end
                else
                    break
                end
            end

            local maxNum = 4
            if table.count(self.teamDojoList_) < maxNum then
                for i = table.count(self.teamDojoList_) + 1, maxNum do
                    table.insert(self.teamDojoList_, {})
                end
            end

            local isUnlock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id20001)
            if isUnlock then
                --找羁绊位
                for k, v in pairs(self.teamDojoList_) do
                    --有了人的位置上羁绊
                    if checkNumber(v.cardId) > 0 then
                        v.fettersId, v.fettersCardId = self:GetTeamFettersCard(v.cardId, self.teamDojoList_)
                    end
                end
            else
                for k, v in pairs(self.teamDojoList_) do
                    v.fettersId, v.fettersCardId = 0, 0
                end
            end
            
            print(table.dump(self.teamDojoList_))

            -- save all teamInfo
            teamComponent:SetTeamByQuestId(LadderQuestId, self.teamDojoList_, Constants.ChooseCardStatus.LadderCompetion, 1, nil, function()
                teamComponent:SetTeamReq(LadderQuestId, function()
                    self:UpdateAllTeamInfo_()
                end)
            end)
        end
    else
        GameUtils.Toast(localize("当前关卡无法变更队伍阵容"))
    end
end

function LadderCompetionMainDialog:GetAllFettersCardsData()
    local allCardsData  = CardUtils.SortCardBySortType(self:GetUsableCardsData(), Constants.SortType.CombatPower, true)
    local teamCardCount = teamComponent:GetMaxSelectNum(LadderQuestId, Constants.ChooseCardStatus.LadderCompetion, 1)
    for cardIndex = #allCardsData, 1, -1 do
        if self.disableIdMap_[tostring(allCardsData[cardIndex].cardId)] then
            table.remove(allCardsData, cardIndex)
        end
    end

    local t = {}
    for k, v in pairs(allCardsData) do
        if not teamComponent:GetTeamCardData(self.teamDojoList_, v.id) then
            table.insert(t, v)
        end
    end

    return t
end

--获取一个最优羁绊卡
function LadderCompetionMainDialog:GetTeamFettersCard(cardId, team)
    local t = self:GetAllFettersCardsData()

    local vo2 = CardConfMgr:GetInstance():GetCardByRefId(cardId)
    --先找特殊羁绊
    for i = 1, table.count(t) do
        local fettersId = CardConfMgr:GetInstance():GetRoleCardSynergiesId(cardId, t[i].cardId)
        --有特殊羁绊
        if fettersId > 0 then
            local isCanChange = teamComponent:IsCanChangeTeamFettersCard(team, t[i].cardId)
            local vo1 = CardConfMgr:GetInstance():GetCardByRefId(t[i].cardId)
            isCanChange = (isCanChange and (checkNumber(vo1.characterId) ~= checkNumber(vo2.characterId)))
            if isCanChange then
                return t[i].id, t[i].cardId
            end
        end
    end

    --特殊羁绊没找到取战斗力最高能上的
    for i = 1, table.count(t) do
        local isCanChange = teamComponent:IsCanChangeTeamFettersCard(team, t[i].cardId)
        local vo1 = CardConfMgr:GetInstance():GetCardByRefId(t[i].cardId)
        isCanChange = (isCanChange and (checkNumber(vo1.characterId) ~= checkNumber(vo2.characterId)))
        if isCanChange then
            return t[i].id, t[i].cardId
        end
    end
    return 0, 0
end

