---@param srcNode LadderCompetionMainTeamNode
---@param destNode LadderCompetionMainTeamNode
function LadderCompetionMainDialog:OnDragTeamNodeToTargetCb_(srcNode, destNode)
    if isNull(srcNode) or isNull(destNode) then return end

    local srcCardIndex  = srcNode:GetCardIndex()
    local destCardIndex = destNode:GetCardIndex()

    -- swap both teamDojo
    local srcTeamDojo  = srcNode:GetTeamDojo()
    local destTeamDojo = destNode:GetTeamDojo()
    self.teamDojoList_[srcCardIndex] = destTeamDojo
    self.teamDojoList_[destCardIndex] = srcTeamDojo

    -- swap both teamNode
    local srcTeamNode  = self.teamNodeList_[srcCardIndex]
    local destTeamNode = self.teamNodeList_[destCardIndex]
    self.teamNodeList_[srcCardIndex]  = destTeamNode
    self.teamNodeList_[destCardIndex] = srcTeamNode

    -- save both teamInfo
    teamComponent:SetTeamByQuestId(LadderQuestId, self.teamDojoList_, Constants.ChooseCardStatus.LadderCompetion, 1, nil, function()
        teamComponent:SetTeamReq(LadderQuestId, function()
            self:UpdateTeamCardAt_(srcCardIndex)
            self:UpdateTeamCardAt_(destCardIndex)
        end, 1)
    end)
end

---红点变动通知处理
---@param type number  @ 1- task 
---@param state      number  @ 红点状态(-1:关闭 0:开启)
function LadderCompetionMainDialog:OnLadderRedPointChangeEventHandler_(type, state)
    local isOpenRedPoint = checkInt(state) == 0
    if type == 1 then
        CfUtils.SetActive(self.BtnTaskRedPoint, isOpenRedPoint)
    end
end

--- 清理情绪共鸣的飞行特效
function LadderCompetionMainDialog:ClearEmotionBonusFlyFX()
    if isNull(self.teamNodeList_) then
        return
    end
    for k, lua in pairs(self.teamNodeList_) do
        if isNotNull(lua) then
            lua:CloseEmotionBonusFlyFX()
        end
    end
end


return LadderCompetionMainDialog